// Generated by scripts/generate-embedded-text.ts from src/workspace; do not edit.

/** The workspace declaration SDK, file name → text (`index.d.ts` re-exports the rest). */
export const WORKSPACE_SDK_DTS: Readonly<Record<string, string>> = {"credentials.d.ts":"/**\n * Credential declarations: `credentials.ts` at the root of a workspace source directory names the\n * saved credentials its workflows use, each by the provider it is for. Never a token: connect one\n * with `sim credentials connect <provider> --name \"<display name>\"`.\n *\n * ```ts\n * // @sim-sdk 1\n * import { defineCredentials } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineCredentials({\n *   slack: { provider: \u0027slack\u0027 },\n *   gmail: { provider: \u0027google-email\u0027, name: \u0027Support inbox\u0027 },\n * })\n * ```\n *\n * A workflow uses one as `credential(\u0027slack\u0027)`, which type-checks against these keys. An apply\n * binds each key to a credential of this workspace: the one bound to it already; else the only\n * credential of the provider no other declared key holds, narrowed to the display name `name`\n * when given. A key nothing binds to, or several credentials could bind to, is reported, and a\n * workflow using it is held back while the rest of the apply goes ahead. Applying the same\n * directory to another workspace binds each key to that workspace\u0027s own credential. Removing a key\n * unbinds it only with `--allow-delete`; the credential itself is never deleted.\n */\n\n/** One declared credential. */\nexport interface CredentialDeclaration {\n  /** The provider the credential is for (`slack`, `google-email`, …). */\n  provider: string\n  /** The display name that picks one of several credentials of the provider. */\n  name?: string\n}\n\n/** Declares the workspace\u0027s credentials by key. Its default export is the whole file. */\nexport declare function defineCredentials<const T extends Record<string, CredentialDeclaration>>(\n  credentials: T\n): T\n\n/**\n * The credential keys a `credentials.ts` declaration adds, each with its provider, as\n * `workspace.d.ts` merges them into `credential(\u0027…\u0027)`.\n */\nexport type DeclaredCredentials<T> = {\n  [K in keyof T]: T[K] extends { provider: infer P } ? { provider: P } : never\n}\n","deployment.d.ts":"/**\n * Deployment declarations: `deployments/<workflow key>.ts` in a workspace source directory deploys\n * `workflows/<workflow key>/`, so its schedule, webhook, API and chat triggers run.\n *\n * ```ts\n * // @sim-sdk 1\n * import { defineDeployment, env } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineDeployment({\n *   live: \u0027draft\u0027,\n *   chat: {\n *     identifier: \u0027support\u0027,\n *     title: \u0027Support\u0027,\n *     auth: { password: env.SUPPORT_CHAT_PASSWORD },\n *     outputs: [{ block: \u0027Answer\u0027, path: \u0027content\u0027 }],\n *   },\n * })\n * ```\n *\n * An apply deploys after it writes the workflows. Removing the file undeploys the workflow, which\n * stops its schedules, webhooks, API and chat, and needs `--allow-delete`. Deploying needs a\n * workspace admin and is refused to a workspace API key. Publishing to an MCP server is not part\n * of source.\n */\nimport type { EnvRef } from \u0027@sim/workflow-sdk\u0027\n\nexport { env, stored } from \u0027@sim/workflow-sdk\u0027\n\n/** Who may open a chat. */\nexport type ChatAuth =\n  | \u0027public\u0027\n  /**\n   * A password from an environment variable, by name, never the value itself; or `stored()`, the\n   * password the chat already stores (valid only for a chat that has one).\n   */\n  | { password: EnvRef }\n  /** These emails (or `@domain.com` patterns), signing in with a code. */\n  | { emails: string[] }\n  /** These emails (or `@domain.com` patterns), signing in through the workspace\u0027s SSO. */\n  | { sso: string[] }\n\n/** One output a chat answers with. */\nexport interface ChatOutput {\n  /** The block\u0027s name, as the workflow names it. */\n  block: string\n  /** The output path on that block (`content`, `result.text`). */\n  path: string\n}\n\n/** The chat a deployment serves. */\nexport interface ChatDeployment {\n  /** The chat\u0027s URL path segment, unique across the platform. */\n  identifier: string\n  title: string\n  description?: string\n  auth: ChatAuth\n  outputs?: ChatOutput[]\n  /** The chat\u0027s look; an omitted field takes the platform default. */\n  customizations?: { primaryColor?: string; welcomeMessage?: string; imageUrl?: string }\n  /** Show the model\u0027s thinking to clients that ask for it. */\n  includeThinking?: boolean\n  /** Show tool calls to clients that ask for them. */\n  includeToolCalls?: boolean\n}\n\n/** A deployment declaration. */\nexport interface DeploymentDeclaration {\n  /**\n   * `\u0027draft\u0027`: an apply deploys the draft whenever it differs from the live version (after this\n   * apply\u0027s workflow edits), as long as it holds only what the workflow folder declares: a draft\n   * edited outside source is not deployed, and the apply warns. `\u0027pinned\u0027`: an apply never\n   * redeploys, and says when the draft differs.\n   */\n  live: \u0027draft\u0027 | \u0027pinned\u0027\n  /** Public: anyone may run the workflow\u0027s API without a key. Private when omitted. */\n  api?: { public?: boolean }\n  /** The chat the deployment serves; none when omitted. */\n  chat?: ChatDeployment\n}\n\n/** Declares a workflow\u0027s deployment. Its default export is the whole file. */\nexport declare function defineDeployment(deployment: DeploymentDeclaration): DeploymentDeclaration\n","file.d.ts":"/**\n * Workspace files need no declaration: every file under `files/` is one workspace file, at the\n * folder path and name it has there (`files/reports/q1.pdf` is `q1.pdf` in the `reports`\n * folder), synced by content hash. Each apply that changes a file\u0027s bytes records a new version\n * of it, so an earlier one can be restored in the Files tab. Files over 10 MB, or whose name no\n * directory can hold (a reserved character, or a path that differs only in letter case from\n * another file or folder), are left out of a get (listed in `.sim/skipped.json`) and never written\n * by an apply; a file the directory no longer holds is deleted only with `--allow-delete`.\n */\nexport {}\n","index.d.ts":"/**\n * The workspace declaration SDK: `import { … } from \u0027@sim/workflow-sdk/workspace\u0027` in the\n * declaration files of a workspace source directory (`tables/<key>.ts`, …). Like the workflow\n * SDK, nothing here runs: the server reads each file statically.\n */\nexport * from \u0027./credentials\u0027\nexport * from \u0027./deployment\u0027\nexport * from \u0027./file\u0027\nexport * from \u0027./knowledge\u0027\nexport * from \u0027./mcp\u0027\nexport * from \u0027./secrets\u0027\nexport * from \u0027./skill\u0027\nexport * from \u0027./table\u0027\nexport * from \u0027./tool\u0027\n","knowledge.d.ts":"/**\n * Knowledge base declarations: `knowledge/<key>/knowledge.ts` in a workspace source directory,\n * beside `knowledge/<key>/docs/`, which holds one file per document.\n *\n * ```ts\n * // @sim-sdk 1\n * import { defineKnowledgeBase } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineKnowledgeBase({\n *   name: \u0027Policies\u0027,\n *   description: \u0027Refund and shipping policies\u0027,\n *   chunking: { maxSize: 1024, minSize: 100, overlap: 200 },\n * })\n * ```\n *\n * Documents sync by content: adding a file to `docs/` uploads it, editing one replaces the stored\n * document (a new upload that takes the old one\u0027s tag values), and removing one deletes it only with\n * `--allow-delete`. Every uploaded or replaced document is indexed after the apply. Documents a\n * connector syncs are never part of source.\n */\n\n/** How documents are split into chunks before they are embedded. */\nexport interface KnowledgeChunking {\n  /** Largest chunk, in tokens (100–4000; 1024 when omitted). */\n  maxSize?: number\n  /** Smallest chunk, in characters (1–2000; 100 when omitted). */\n  minSize?: number\n  /** Tokens neighbouring chunks share (0–500; 200 when omitted). */\n  overlap?: number\n  strategy?: \u0027auto\u0027 | \u0027text\u0027 | \u0027regex\u0027 | \u0027recursive\u0027 | \u0027sentence\u0027 | \u0027token\u0027\n  strategyOptions?: {\n    /** The split pattern of the `regex` strategy. */\n    pattern?: string\n    separators?: string[]\n    recipe?: \u0027plain\u0027 | \u0027markdown\u0027 | \u0027code\u0027\n    /** `regex` only: every match is its own chunk. */\n    strictBoundaries?: boolean\n  }\n}\n\n/** A knowledge base declaration. */\nexport interface KnowledgeBaseDeclaration {\n  name: string\n  description?: string\n  /** The knowledge base folder path (`/support`); the workspace root when omitted. */\n  folder?: string\n  /**\n   * Applies to documents indexed from now on; stored chunks keep the settings they were made\n   * with.\n   */\n  chunking?: KnowledgeChunking\n  /** The embedding model, fixed when the knowledge base is created. */\n  embeddingModel?: string\n}\n\n/** Declares a knowledge base. Its default export is the whole file. */\nexport declare function defineKnowledgeBase(\n  knowledgeBase: KnowledgeBaseDeclaration\n): KnowledgeBaseDeclaration\n","mcp.d.ts":"/**\n * MCP server declarations: `mcp/<key>.ts` declares one server the workspace\u0027s agents call tools\n * on.\n *\n * ```ts\n * // @sim-sdk 1\n * import { defineMcpServer, env } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineMcpServer({\n *   name: \u0027GitHub\u0027,\n *   url: \u0027https://api.githubcopilot.com/mcp/\u0027,\n *   headers: { Authorization: \u0027Bearer {{GITHUB_TOKEN}}\u0027, \u0027X-Team\u0027: env.GITHUB_TEAM },\n * })\n * ```\n *\n * A workflow names the server by its key and one of its tools by name:\n * `mcp(\u0027github\u0027).tool(\u0027create_issue\u0027)`. Secrets never sit in source: a credential header\n * (`Authorization`, `Cookie`, or a name with `key`, `token`, `secret`, `auth`, …) holds env\n * references (`env.NAME`, or `{{NAME}}` in its text after a scheme such as `Bearer`) or\n * `stored()`, which keeps the value the server holds. The server\u0027s id derives from its URL, so a\n * `url` with another host or path replaces the server; a new query string updates it in place.\n */\nimport type { EnvRef } from \u0027@sim/workflow-sdk\u0027\n\nexport { env, stored } from \u0027@sim/workflow-sdk\u0027\n\n/** A header value: text (`{{NAME}}` names an env variable), `env.NAME`, or `stored()`. */\nexport type McpHeaderValue = string | EnvRef\n\n/** How the server authenticates. */\nexport interface McpServerAuth {\n  /** `headers` (the default) sends the declared headers; `oauth` signs in with an OAuth grant. */\n  type: \u0027none\u0027 | \u0027headers\u0027 | \u0027oauth\u0027\n  /** A pre-registered OAuth client, for a server without dynamic client registration. */\n  clientId?: string\n}\n\n/** An MCP server declaration. */\nexport interface McpServerDeclaration {\n  /** The display name; the key when left out. */\n  name?: string\n  description?: string\n  /** An `http://` or `https://` URL. A new host or path replaces the server; a new query does not. */\n  url: string\n  transport?: \u0027streamable-http\u0027\n  headers?: { [name: string]: McpHeaderValue }\n  /** `{ type: \u0027headers\u0027 }` when left out. The OAuth client secret is set in the server settings. */\n  auth?: McpServerAuth\n  /** Milliseconds a request waits; 30000 when left out. */\n  timeout?: number\n  /** 3 when left out. */\n  retries?: number\n  /** `true` when left out. */\n  enabled?: boolean\n}\n\n/** Declares an MCP server. Its default export is the whole file. */\nexport declare function defineMcpServer(server: McpServerDeclaration): McpServerDeclaration\n","secrets.d.ts":"/**\n * Secret declarations: `secrets.ts` at the root of a workspace source directory names the\n * workspace secrets its workflows read, by name and what each is for. Never a value: set one with\n * `sim secrets set <NAME> --scope workspace`, or in the workspace\u0027s secrets settings.\n *\n * ```ts\n * // @sim-sdk 1\n * import { defineSecrets } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineSecrets({\n *   ANTHROPIC_API_KEY: { description: \u0027Model access for the support agent\u0027 },\n *   STRIPE_KEY: {},\n * })\n * ```\n *\n * A workflow reads one as `env.NAME`, which type-checks against these names. An apply sets only\n * descriptions: a name the workspace holds no value for is reported, and a workflow using it is\n * held back (not written) while the rest of the apply goes ahead. Removing a name changes nothing\n * on the server.\n */\n\n/** One declared secret. */\nexport interface SecretDeclaration {\n  /** What the secret is for, shown to teammates (at most 500 characters). */\n  description?: string\n}\n\n/** Declares the workspace\u0027s secrets by name. Its default export is the whole file. */\nexport declare function defineSecrets<const T extends Record<string, SecretDeclaration>>(\n  secrets: T\n): T\n\n/** The env names a `secrets.ts` declaration adds, as `workspace.d.ts` merges them into `env`. */\nexport type DeclaredSecretNames<T> = { [K in keyof T]: true }\n","skill.d.ts":"/**\n * Skills are markdown, not TypeScript: `skills/<key>.md` is a frontmatter block of `name` and\n * `description`, then the skill\u0027s content.\n *\n * ```md\n * ---\n * name: tone\n * description: \"Answer in the support team\u0027s voice: short, warm, specific.\"\n * ---\n * Write like a person, not a policy.\n * ```\n *\n * A value is plain text on one line, or a JSON string (`\"…\"`) when it holds a line break,\n * surrounding spaces, quotes, `: ` or ` #`, ends in `:`, or starts with anything but a letter,\n * digit or `(`. Quote a value YAML would read as a boolean, number or date (`\"yes\"`, `\"1e3\"`) too,\n * so other markdown tools read it as text. The name is kebab-case; a workflow names the skill by\n * its key, `skill(\u0027tone\u0027)`. This module declares nothing.\n */\nexport {}\n","table.d.ts":"/**\n * Table declarations: `tables/<key>.ts` in a workspace source directory.\n *\n * ```ts\n * // @sim-sdk 1\n * import { column, defineTable } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineTable({\n *   name: \u0027leads\u0027,\n *   columns: {\n *     email: column.string({ required: true, unique: true }),\n *     status: column.select({ options: [\u0027new\u0027, \u0027won\u0027, \u0027lost\u0027] }),\n *     score: column.number(),\n *   },\n * })\n * ```\n *\n * A column\u0027s object key is its source key and stays bound to the stored column; `name` renames\n * the stored column while keeping its cells.\n *\n * Rows are part of source only when `rows` opts in: `tables/<key>.rows.jsonl` beside the\n * declaration holds one JSON object per line, keyed by column key (a select cell by option name).\n * `{ mode: \u0027seed\u0027 }` writes them into the table when an apply creates it (or adopts it empty);\n * `{ mode: \u0027managed\u0027, key }` keeps the table\u0027s rows equal to the file, each matched by the unique\n * `key` column (removing a row needs `--allow-delete`); a stored row whose `key` cell is empty is\n * left out of the file and kept as it is.\n */\nimport type { Json } from \u0027@sim/workflow-sdk\u0027\n\ndeclare const COLUMN: unique symbol\n\n/**\n * A declared column: the cell type `T` it holds, the name `N` it is stored under, and whether\n * every row must hold a value (`R`); a cell of a column that is not required may be empty (`null`).\n */\nexport interface Column<T, N extends string | undefined = undefined, R extends boolean = false> {\n  readonly [COLUMN]: { value: T; name: N; required: R }\n}\n\n/** Options every column type takes. */\nexport interface ColumnOptions<\n  N extends string | undefined = string | undefined,\n  R extends boolean = boolean,\n> {\n  /** The stored column name, when it differs from the column\u0027s key. */\n  name?: N\n  /** Every row must hold a value. */\n  required?: R\n  /** No two rows may hold the same value. */\n  unique?: boolean\n}\n\n/** The shared options a `select` column takes: never `unique`. */\ntype SelectOptions<N extends string | undefined, R extends boolean> = Omit<\n  ColumnOptions<N, R>,\n  \u0027unique\u0027\n>\n\n/** The column helpers: `column.string()`, `column.select({ options: [...] })`, … */\nexport declare const column: {\n  string<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R>\n  ): Column<string, N, R>\n  number<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R>\n  ): Column<number, N, R>\n  /** A number shown as money; `currencyCode` is an ISO 4217 code (`USD` when omitted). */\n  currency<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R> & { currencyCode?: string }\n  ): Column<number, N, R>\n  boolean<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R>\n  ): Column<boolean, N, R>\n  /** An ISO 8601 date or date-time string. */\n  date<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R>\n  ): Column<string, N, R>\n  /** A time to live: a date-time after which the row expires. A table holds at most one. */\n  ttl<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R>\n  ): Column<string, N, R>\n  json<const N extends string | undefined = undefined, const R extends boolean = false>(\n    options?: ColumnOptions<N, R>\n  ): Column<Json, N, R>\n  /** One option per cell, from `options`. */\n  select<\n    const O extends readonly [string, ...string[]],\n    const N extends string | undefined = undefined,\n    const R extends boolean = false,\n  >(options: SelectOptions<N, R> & { options: O; multiple?: false }): Column<O[number], N, R>\n  /** Several options per cell. */\n  select<\n    const O extends readonly [string, ...string[]],\n    const N extends string | undefined = undefined,\n    const R extends boolean = false,\n  >(options: SelectOptions<N, R> & { options: O; multiple: true }): Column<O[number][], N, R>\n}\n\n/** Any column, whatever it holds. */\ntype AnyColumn = Column<unknown, string | undefined, boolean>\n\n/** A table declaration. */\nexport interface TableDeclaration<C extends Record<string, AnyColumn> = Record<string, AnyColumn>> {\n  /** The table name: a letter or `_`, then letters, digits and `_`. */\n  name: string\n  description?: string\n  /** The table folder path (`/reports`); the workspace root when omitted. */\n  folder?: string\n  columns: C\n  /** Rows as source, from `tables/<key>.rows.jsonl`; omitted leaves rows out of source. */\n  rows?: TableRows<keyof C & string>\n}\n\n/**\n * How a table\u0027s rows are source: `seed` rows go into the table once, when an apply creates it;\n * `managed` rows are the whole table, matched to stored rows by the unique `key` column.\n */\nexport type TableRows<K extends string = string> = { mode: \u0027seed\u0027 } | { mode: \u0027managed\u0027; key: K }\n\n/** Declares a table. Its default export is the whole file. */\nexport declare function defineTable<const C extends Record<string, AnyColumn>>(\n  table: TableDeclaration<C>\n): TableDeclaration<C>\n\n/** The stored name of column `K`: its `name` option, else its key. */\ntype StoredName<K, C> = C extends Column<unknown, infer N, boolean>\n  ? [N] extends [string]\n    ? N\n    : K\n  : K\n\n/** A cell of column `C`: its value, or `null` when the column is not required. */\ntype CellOf<C> = C extends Column<infer V, infer _N, infer R>\n  ? R extends true\n    ? V\n    : V | null\n  : never\n\n/**\n * A declared table\u0027s row, keyed by stored column name: `RowOf<typeof leads>`. A cell of a column\n * that is not required may be `null`.\n */\nexport type RowOf<T> = T extends TableDeclaration<infer C>\n  ? { [K in keyof C as StoredName<K, C[K]>]: CellOf<C[K]> }\n  : never\n","tool.d.ts":"/**\n * Custom tool declarations: `tools/<key>.ts`, with the tool\u0027s code beside it in `tools/<key>.js`.\n *\n * ```ts\n * // @sim-sdk 1\n * import { codeFile, defineTool } from \u0027@sim/workflow-sdk/workspace\u0027\n *\n * export default defineTool({\n *   title: \u0027Lookup order\u0027,\n *   schema: {\n *     type: \u0027function\u0027,\n *     function: {\n *       name: \u0027lookup_order\u0027,\n *       description: \u0027Find an order by id.\u0027,\n *       parameters: {\n *         type: \u0027object\u0027,\n *         properties: { orderId: { type: \u0027string\u0027 } },\n *         required: [\u0027orderId\u0027],\n *       },\n *     },\n *   },\n *   code: codeFile(\u0027./lookup-order.js\u0027),\n * })\n * ```\n *\n * The code file runs with each parameter as a variable; `$env.NAME` reads an environment variable\n * by name. The key is the tool\u0027s identity: a workflow names it as `customTool(\u0027lookup-order\u0027)`.\n * Code holding a literal credential prints as `code: stored()`, which keeps the code the server\n * holds without showing it.\n */\nimport type { CodeFileRef, Json } from \u0027@sim/workflow-sdk\u0027\n\nexport { codeFile, stored } from \u0027@sim/workflow-sdk\u0027\n\n/** JSON as an object literal writes it: an optional member may be absent. */\ntype SchemaJson = Json | readonly SchemaJson[] | { readonly [key: string]: SchemaJson | undefined }\n\n/** The function declaration a model calls the tool by, stored verbatim. */\nexport interface ToolSchema {\n  type: \u0027function\u0027\n  function: {\n    /** What the model calls: letters, digits, `_` and `-`, at most 64 characters. */\n    name: string\n    description?: string\n    /** A JSON Schema object describing the arguments. */\n    parameters: {\n      type: \u0027object\u0027\n      properties: { [name: string]: Json }\n      required?: string[]\n      readonly [extra: string]: SchemaJson | undefined\n    }\n    readonly [extra: string]: SchemaJson | undefined\n  }\n  readonly [extra: string]: SchemaJson | undefined\n}\n\n/** A custom tool declaration. */\nexport interface ToolDeclaration {\n  /** The tool\u0027s display title, unique in the workspace. */\n  title: string\n  schema: ToolSchema\n  /** `codeFile(\u0027./<key>.js\u0027)`, the code inline as a string, or `stored()` to keep the stored code. */\n  code: CodeFileRef | string\n}\n\n/** Declares a custom tool. Its default export is the whole file. */\nexport declare function defineTool(tool: ToolDeclaration): ToolDeclaration\n"}
